{
"practices_used": [
  {
    "order": 1,
    "practice": "Representing",
    "why": "The student must interpret the given statistical information—mean and MAD—and translate it into a mathematical understanding of variability and sampling. This involves recognizing that the mean (30 mph) and MAD (3 mph) represent a central tendency and spread, and using these to evaluate claims about sample means and population estimates. This aligns with the descriptor: 'Create and use a statistical model to answer a statistical question or make a prediction about a data set.'",
    "likely_errors": "A student might misinterpret MAD as standard deviation or confuse it with range, leading to incorrect judgments about variability. This is moderately likely for students unfamiliar with MAD, especially if they’ve only seen standard deviation."
  },
  {
    "order": 2,
    "practice": "Justifying and Proving",
    "why": "The student must evaluate each statement for truth based on statistical reasoning, such as understanding that larger samples reduce sampling variability, and that a sample mean is likely to fall within a range around the population mean (e.g., within ±2 MADs). They must justify why some statements are true (e.g., a larger sample improves accuracy) and others false (e.g., sample means won’t necessarily be identical across samples). This matches the descriptor: 'Make, justify, or defend conclusions and generalizations about numerical relationships or patterns, including why they are valid or will always hold.'",
    "likely_errors": "A student might incorrectly assume that sample means are always identical across samples or that the median must be within a specific range just because the mean is. This is likely if they lack understanding of sampling variability and the difference between mean and median."
  },
  {
    "order": 3,
    "practice": "Abstracting and Generalizing",
    "why": "The student must generalize from the given sample (n=30, mean=30, MAD=3) to broader claims about sampling behavior, such as the expected variability in future samples or the impact of sample size on accuracy. For example, they must recognize that increasing sample size improves reliability and that a second sample is likely to have a mean within a predictable range (e.g., 24–36 mph, which is ±2 MADs). This matches the descriptor: 'Identify patterns in numbers, figures, sequences, tables, or graphs and generalize them using words, pictures, or symbols.'",
    "likely_errors": "A student might fail to generalize beyond the given data, assuming that the mean of any sample must be exactly 30, or not recognize that larger samples reduce variability. This is moderately likely for students who have not been exposed to sampling distributions or the law of large numbers."
  }
],
"practices_not_used": [
  {
    "practice": "Mathematical Modeling",
    "why": "The item does not require the student to create or revise a model of a real-world situation, nor to identify a problem to be solved through mathematization. The scenario is already fully mathematized (mean and MAD are given), and the task is to evaluate statements about statistical inference, not to build a model from context."
  },
  {
    "practice": "Collaborative Mathematics",
    "why": "The item presents no dialogue, peer work, or social interaction. The student evaluates statements independently and selects answers without engaging with another person’s reasoning or building on a peer’s contribution."
  },
  {
    "practice": "Procedural Fluency",
    "why": "While the student uses basic statistical concepts, no procedural computation is required beyond interpreting given values (mean and MAD). There is no need to compute a mean, MAD, or any other statistic, nor to apply algorithms. The task is conceptual and evaluative, not computational."
  }
]
}

